{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Not Enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server access logging enabled, which prevents tracking of requests made to the bucket for security auditing and troubleshooting."
    },
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 Bucket Public Read/Write ACLs",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "While 'private' is set, explicit ACL configuration is deprecated in favor of Block Public Access settings. Without `aws_s3_bucket_public_access_block`, the bucket may be vulnerable if default permissions change or if other policies allow public access."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket Encryption Not Configured",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "Server-side encryption is not explicitly configured for the bucket. Data at rest should be encrypted using SSE-S3 or SSE-KMS to protect sensitive information."
    },
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 Bucket Versioning Disabled",
      "resource": "aws_s3_bucket.b",
      "severity": "LOW",
      "explanation": "Versioning is not enabled on the bucket. Enabling versioning provides an additional layer of protection against accidental deletion or overwriting of objects."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "b" {
  bucket = "my-tf-test-bucket-ggff"
}

resource "aws_s3_bucket_acl" "b" {
  bucket = aws_s3_bucket.b.id
  acl    = "private"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "b" {
  bucket = aws_s3_bucket.b.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "b" {
  bucket = aws_s3_bucket.b.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "b" {
  bucket = aws_s3_bucket.b.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "b" {
  bucket        = aws_s3_bucket.b.id
  target_bucket = aws_s3_bucket.b.id # In production, this should point to a separate log bucket
  target_prefix = "log/"
}",
  "fix_summary": "Removed the deprecated inline `acl` argument from the main resource and moved it to a dedicated `aws_s3_bucket_acl` resource. Added `aws_s3_bucket_server_side_encryption_configuration` to enforce AES256 encryption at rest. Added `aws_s3_bucket_versioning` to enable object versioning. Added `aws_s3_bucket_public_access_block` to strictly prevent public access. Added `aws_s3_bucket_logging` to enable access logs (note: in a real scenario, the target bucket should be a separate, secure logging bucket)."
}
